#!/usr/bin/env node
/**
 * Sync episode metadata from the source-of-truth Google Sheet
 * "Storys 節目集數總表 v1" into src/data/episodes.json.
 *
 * The sheet must be shared with "Anyone with the link can view".
 *
 * Run manually:   npm run sync-episodes
 * Override sheet: STORYS_SHEET_ID=<id> STORYS_SHEET_GID=<gid> npm run sync-episodes
 *
 * Summary text (the `summary` field) is generated by a separate step
 * (scripts/generate-summaries.mjs) and is NOT touched here — this script
 * preserves any existing summary when a row already has one.
 */

import { writeFile, readFile } from "node:fs/promises";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Default = the Storys Master Sheet's Episodes tab (repointed 2026-07-02; the old
// Michelle sheet 1aYKpPGqVYiUCG4Ky2p_bPwAhigAGRABdIPQ07d_num8 is retired as a source).
const SHEET_ID =
  process.env.STORYS_SHEET_ID ?? "1axbM6qDG1pz1jCZ3_NyBZWtgcNbNb6cNtnou7FBI2P4";
const SHEET_GID = process.env.STORYS_SHEET_GID ?? "0";
const CSV_URL = `https://docs.google.com/spreadsheets/d/${SHEET_ID}/export?format=csv&gid=${SHEET_GID}`;
const OUTPUT = resolve(__dirname, "..", "src", "data", "episodes.json");

// ---------------------------------------------------------------------------
// CSV parsing (RFC 4180-ish: handles quoted fields, embedded commas/newlines,
// and "" escapes). No external deps.
// ---------------------------------------------------------------------------
function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = "";
  let inQuotes = false;
  let i = 0;
  while (i < text.length) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i += 2; continue; }
        inQuotes = false; i++; continue;
      }
      field += c; i++;
    } else {
      if (c === '"') { inQuotes = true; i++; continue; }
      if (c === ",") { row.push(field); field = ""; i++; continue; }
      if (c === "\n" || c === "\r") {
        if (c === "\r" && text[i + 1] === "\n") i++;
        row.push(field); field = "";
        rows.push(row); row = [];
        i++; continue;
      }
      field += c; i++;
    }
  }
  if (field !== "" || row.length > 0) { row.push(field); rows.push(row); }
  return rows.filter((r) => r.some((cell) => cell !== ""));
}

// ---------------------------------------------------------------------------
// Field normalizers
// ---------------------------------------------------------------------------
const clean = (v) => {
  if (v == null) return null;
  const s = String(v).trim();
  if (s === "" || s === "無" || s === "缺") return null;
  return s;
};
// Only accept http(s) URLs — a sheet-authored `javascript:`/`data:` URL must never
// reach an href (same guard as sync.mjs's httpUrl for brand websites).
const httpUrl = (v) => {
  const s = clean(v);
  return s && /^https?:\/\//i.test(s) ? s : null;
};
const num = (v) => {
  const s = clean(v);
  if (s == null) return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};
const date = (v) => {
  const s = clean(v);
  if (s == null) return null;
  // ISO 8601 (YYYY-MM-DD) — the sheet already uses this.
  return /^\d{4}-\d{2}-\d{2}$/.test(s) ? s : s;
};

// ---------------------------------------------------------------------------
// Row → SyncedEpisode
// ---------------------------------------------------------------------------
function normalizeRow(row) {
  const [
    epNum,
    publishDate,
    titleZh,
    titleEn,
    guestName,
    guestTitle,
    brandNameZh,
    brandId,
    appleId,
    spotifyId,
    soundonUrl,
    kkboxUrl,
    durationSec,
    transcriptFile,
    coverFile,
  ] = row;
  return {
    num: num(epNum),
    publishDate: date(publishDate),
    titleZh: clean(titleZh) ?? "",
    titleEn: clean(titleEn),
    guestName: clean(guestName),
    guestTitle: clean(guestTitle),
    brandNameZh: clean(brandNameZh),
    brandId: clean(brandId),
    appleId: clean(appleId),
    spotifyId: clean(spotifyId),
    soundonUrl: httpUrl(soundonUrl),
    kkboxUrl: httpUrl(kkboxUrl),
    durationSec: num(durationSec),
    transcriptFile: clean(transcriptFile),
    coverFile: clean(coverFile),
    summary: null,
  };
}

async function loadExistingSummaries() {
  try {
    const raw = await readFile(OUTPUT, "utf8");
    const json = JSON.parse(raw);
    const map = new Map();
    for (const item of json.items ?? []) {
      if (item?.num != null && item.summary) map.set(item.num, item.summary);
    }
    return map;
  } catch {
    return new Map();
  }
}

async function main() {
  console.log(`[sync-episodes] Fetching ${CSV_URL}`);
  const res = await fetch(CSV_URL);
  if (!res.ok) {
    throw new Error(
      `Sheet fetch failed: HTTP ${res.status}. ` +
        `Make sure the sheet is shared as "Anyone with the link can view".`,
    );
  }
  const csv = await res.text();
  const rows = parseCsv(csv);
  const [header, ...body] = rows;
  console.log(`[sync-episodes] CSV header: ${header.length} cols, ${body.length} rows`);

  // normalizeRow parses POSITIONALLY — guard the column order so an inserted or
  // reordered sheet column fails loudly instead of silently shifting every field.
  const EXPECTED_HEADER = [
    "集數", "上線日期", "中文標題", "英文標題", "來賓姓名", "來賓職稱",
    "品牌中文名", "brand_id", "Apple Podcasts ID", "Spotify Episode ID",
    "SoundOn 連結", "KKBOX 連結", "集數時長（秒）", "逐字稿 Drive 連結", "封面圖 Drive 連結",
  ];
  const headerTrim = header.map((h) => h.trim());
  const mismatch = EXPECTED_HEADER.findIndex((h, i) => headerTrim[i] !== h);
  if (mismatch !== -1) {
    throw new Error(
      `Sheet column order changed: col ${mismatch + 1} is ${JSON.stringify(headerTrim[mismatch])}, ` +
        `expected ${JSON.stringify(EXPECTED_HEADER[mismatch])}. ` +
        `Update EXPECTED_HEADER + normalizeRow together, then re-run.`,
    );
  }

  const existingSummaries = await loadExistingSummaries();

  const items = body
    .map(normalizeRow)
    .filter((ep) => ep.num != null)
    .map((ep) => ({
      ...ep,
      summary: existingSummaries.get(ep.num) ?? null,
    }))
    .sort((a, b) => (b.num ?? 0) - (a.num ?? 0));

  const out = {
    syncedAt: new Date().toISOString(),
    items,
  };
  await writeFile(OUTPUT, JSON.stringify(out, null, 2) + "\n", "utf8");
  console.log(`[sync-episodes] Wrote ${items.length} episodes to ${OUTPUT}`);
  console.log(
    `[sync-episodes] Preserved summaries for ${
      items.filter((i) => i.summary).length
    } episodes.`,
  );
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
